      vbool4_t   half1  = __riscv_vmsltu_vx_u16m4_b4(vid, 16, 32);
      vint16m4_t scale  = __riscv_vmerge_vxm_i16m4(
                            __riscv_vmv_v_x_i16m4(ls2, 32), ls1, half1, 32);

      /* FUSED widening MAC: vacc += prod * scale (i16*i16 -> i32). NO per-group reduce. */
